{
  "speakers": [
    {
      "speaker_id": "sp2",
      "overview": "sp2 提到安保部门无迟到现象因三班倒，闭店时仍安排人员在店内休息以防贵重物品丢失；指出酒后闹事因当事人醉酒无法协商；建议对涉嫌卖毒品者先控制；提到部分女性藏毒品于搜身发现不了的位置；指出金属物品扫描不出的隐患；建议周日或周六进行现场抽奖活动以增加人气；提到酒吧入场需支付费用后可进行免费抽奖"
    },
    {
      "speaker_id": "sp5",
      "overview": "sp5 说明卡座和散台数量，周一至周五人少，周末爆满；针对不同消费群体提供套餐；营销部无迟到因提前安排客户；建议对迟到人员采取批评和罚款措施；指出酒吧灯光和音乐设施不足影响体验；提议在节日如七夕、情人节举办主题活动；建议每月举办主题派对以提升流水"
    },
    {
      "speaker_id": "sp7",
      "overview": "sp7 指出安保部门应招聘女性保安；提到上月主题派对效果良好，建议每月举办主题派对以提升流水；警告过度宣传潜在客户可能损害口碑；强调潜在客户首次消费后可能成为固定客户"
    }
  ]
}
